// expandTilde expands a leading "~" or "~/" to the user home directory.
// Returns "" if the pattern needs expansion but the home dir is unavailable.
func expandTilde(pattern string) string {
	if pattern == "~" || strings.HasPrefix(pattern, "~/") {
		home, err := os.UserHomeDir()
		if err != nil {
			return ""
		}
		return filepath.ToSlash(filepath.Join(home, strings.TrimPrefix(pattern, "~")))
	}
	return filepath.ToSlash(pattern)
}

// matchesExcludePath reports whether worktreeRoot matches any exclude_paths
// pattern. A pattern also excludes everything under it (p matches, or p/**
// matches). Broken patterns (unexpandable ~, invalid glob) are skipped so one
// bad entry cannot disable the rest of the exclude list.
func matchesExcludePath(patterns []string, worktreeRoot string) bool {
	root := filepath.ToSlash(worktreeRoot)
	for _, p := range patterns {
		expanded := expandTilde(p)
		if expanded == "" {
			continue
		}
		if ok, err := doublestar.Match(expanded, root); err == nil && ok {
			return true
		}
		if ok, err := doublestar.Match(expanded+"/**", root); err == nil && ok {
			return true
		}
	}
	return false
}

// matchesExcludeOrigin reports whether the normalized origin ("host/owner/repo")
// matches any exclude_origins pattern. An empty origin matches nothing.
func matchesExcludeOrigin(patterns []string, normalizedOrigin string) bool {
	if normalizedOrigin == "" {
		return false
	}
	for _, p := range patterns {
		if ok, err := doublestar.Match(strings.ToLower(p), normalizedOrigin); err == nil && ok {
			return true
		}
	}
	return false
}
```

